import {
  Component,
  Element,
  h,
  Prop,
  State,
  Watch,
  Event,
  EventEmitter,
  Host,
  ComponentInterface,
} from '@stencil/core';
import { dir } from '@src/shared/i18n';
import { DrawerCloseReason, DrawerPlacement, DrawerSize } from './types';
import { Slot, AllSlots, Uncontrollable } from '@src/framework/decorators';
import { registerPluginManager } from '@src/shared/unclassified/plugin';
import { sendActionTracking, sendDurationTracking, sendExposeTracking } from '@src/shared/unclassified/tracking';
import { asObject } from '@src/shared/type-utils';
import { CSSProperties, formatCSSLength } from '@src/shared/dom';
import { KsIconClose, KsIconFold, KsIconUnfold } from '@fe-infra/keystone-icons-stencil';

const prefix = 'drawer';

const expandTooltipDelay = { open: 0, close: 0 };

/**
 * @slot default - Main content rendered inside the drawer body when the `body` slot is not provided.
 * @slot sideNav - Slot for content to be displayed in the side navigation area when `hasSideNav` is true.
 * @slot header - Slot for custom header content. Overrides `title`.
 * @slot body - Slot for the main body content of the drawer. This will replace the content and also the integrated padding.
 * @slot footer - Slot for custom footer content. Overrides default confirm/cancel buttons.
 * @part backdrop - The backdrop element.
 * @part base - The base container of the component.
 * @part side - The side panel that contains the close button and optional navigation content.
 * @part header - The header container.
 * @part body - The body container.
 * @part footer - The footer container.
 */
@Component({
  tag: 'ks-drawer',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsDrawer implements ComponentInterface {
  static vModel = { prop: 'open', event: 'ksOpenChange' };
  // 内部变量 ----------
  @Element() el!: HTMLKsDrawerElement;
  private drawerRef?: HTMLElement;
  private backdropRef?: HTMLElement;
  private activeAnimations: Animation[] = [];
  private animationTargetOpen?: boolean;
  private transitionToken = 0;
  private didLoad = false;
  private closeRequestInFlight = false;

  /** Whether the drawer is currently open. */
  @Prop() open?: boolean;
  /** Indicates whether the default status of the drawer is open, in uncontrolled mode. */
  @Prop() defaultOpen?: boolean;
  @Uncontrollable('open', 'defaultOpen', 'ksOpenChange') @State() mergedOpen?: boolean;
  /** The size of the drawer. */
  @Prop() size: DrawerSize = 'md';
  /** The width of the drawer. Overrides the default width based on the size. */
  @Prop() width?: string | number;
  /** Whether the drawer is displayed with a side navigation. If `true`, the drawer will be displayed with a side navigation. */
  @Prop() hasSideNav = false;
  /** Whether the backdrop is shown. If `true`, an overlay outside the drawer will be displayed. */
  @Prop() backdrop: boolean | { transparent?: boolean } = true;
  /** Whether the drawer is closeable. If `true`, the drawer can be closed by clicking the backdrop or pressing the escape key. */
  @Prop() closeable: boolean | { backdrop?: boolean; icon?: boolean; keyboard?: boolean } = true;
  /** The placement of the drawer, indicating which edge of the screen the drawer slides out from. */
  private placement: DrawerPlacement = 'end';
  /**  The text displayed as the title of the drawer. */
  @Prop() title = '';
  /** Whether the drawer is expandable when sideNav is present. If `true`, an expand button will be displayed in the header, allowing users to toggle between normal and expanded states. */
  @Prop() expandable = false;
  /** The offset of the drawer from the screen edges. */
  @Prop() topOffset?: string | number = 0;
  /** (React-only) Whether the drawer should be appended to the body element. */
  @Prop() appendToBody = false;
  /** Whether to show a divider between the sideNav and body. Defaults to `auto`, which shows a divider when the content is scrollable. When `true`, always show a divider. Note that `false` is explicitly disallowed in Keystone design. */
  @Prop() divider: 'auto' | true = 'auto';

  /** Called when the drawer receives a close request from the keyboard, close icon, or backdrop. Return `false` to prevent the drawer from closing. */
  @Prop() onClose?: (reason: DrawerCloseReason) => Promise<boolean> | boolean | (Promise<void> | void);

  /** A function called after the drawer opens and the opening animation completes. */
  @Prop() afterOpen?: () => void | Promise<void>;
  /** A function called after the drawer closes and the closing animation completes. */
  @Prop() afterClose?: () => void | Promise<void>;

  /** Override the zIndex setting */
  @Prop() zIndex?: number;

  @Slot({ slotname: 'header' }) private headerSlots?: AllSlots;
  @Slot({ slotname: 'footer' }) private footerSlots?: AllSlots;
  /** Triggered when the drawer toggles between its default and expanded states. Emits the next expanded state. */
  @Event({ bubbles: false, composed: false }) ksExpandedChange!: EventEmitter<boolean>;

  /**
   * Emits when the drawer open state changes.
   *
   * @private Reserved for `v-model` usage of Vue.
   */
  @Event() ksOpenChange!: EventEmitter<boolean>;

  // state --------------------
  @State() innerVisible = false;
  @State() drawerTransform?: string;
  @State() backdropOpacity?: string;
  @State() confirmLoading = false;
  @State() cancelLoading = false;
  @State() expanded = false;
  @State() expandTooltipOpen = false;
  @State() _bodyScrollable = false;
  private tooltipAnimating = false;
  private tooltipTimeout?: ReturnType<typeof setTimeout>;
  private bodyResizeObserver?: ResizeObserver;
  private bodyRef?: HTMLElement;

  private get _showDivider() {
    return this.divider === 'auto' ? this._bodyScrollable : this.divider;
  }

  /** Tooltip open logic needed to be enforced due to animation transition. */
  private setTooltipFor(val: boolean, time = 0): void {
    if (!this.tooltipAnimating) {
      this.expandTooltipOpen = val;
    }
    this.tooltipAnimating = true;

    if (this.tooltipTimeout) {
      clearTimeout(this.tooltipTimeout);
    }

    this.tooltipTimeout = setTimeout(() => {
      this.tooltipAnimating = false;
      this.tooltipTimeout = undefined;
    }, time);
  }

  // watch --------------------
  @Watch('mergedOpen')
  watchVisible(newValue: boolean) {
    if (!this.didLoad) {
      return;
    }
    newValue ? this._open() : this._close('programmatic');
  }

  get innerPlacement() {
    if (this.placement === 'end' && dir() === 'rtl') {
      return 'left';
    } else {
      return 'right';
    }
  }

  private get translateXOffset() {
    return this.innerPlacement === 'left' ? '-100%' : '100%';
  }

  // Method --------------------
  /** Method to open the drawer. */
  private _open = async () => {
    this.closeRequestInFlight = false;
    if (this.innerVisible && this.animationTargetOpen !== false) {
      return;
    }

    const completed = await this.visibleByAnime(true);
    if (!completed || this.mergedOpen !== true) {
      return;
    }

    this.afterOpen?.();
    sendExposeTracking(this.el as HTMLElement, { eventType: 'popup' });
    sendDurationTracking(this.el as HTMLElement, { eventType: 'popup', reset: true });
  };

  private _close = async (reason: DrawerCloseReason | 'programmatic'): Promise<boolean> => {
    if (!this.innerVisible && this.animationTargetOpen !== true) {
      return false;
    }

    if (reason === 'programmatic') {
      this.closeRequestInFlight = true;
      const completed = await this.visibleByAnime(false);
      if (!completed || this.mergedOpen !== false) {
        return false;
      }

      this.afterClose?.();
      sendDurationTracking(this.el as HTMLElement, { eventType: 'popup' });
      return true;
    }

    if (this.animationTargetOpen === true || this.closeRequestInFlight) {
      return false;
    }

    this.closeRequestInFlight = true;
    const closeRequestToken = this.transitionToken;

    try {
      if ((await this.onClose?.(reason)) === false) {
        return false;
      }
      if (closeRequestToken !== this.transitionToken) {
        return false;
      }

      this.mergedOpen = false;
      return true;
    } finally {
      if (this.mergedOpen === true && this.animationTargetOpen !== false) {
        this.closeRequestInFlight = false;
      }
    }
  };

  private _expand = (newExpand: boolean) => {
    if (!this.innerVisible) {
      return;
    }
    this.ksExpandedChange.emit(newExpand);
  };

  constructor() {
    registerPluginManager(this.el);
  }
  private async closeHandler(reason: DrawerCloseReason) {
    this.cancelLoading = true;
    const closed = await this._close(reason);
    this.cancelLoading = false;
    if (closed) {
      sendActionTracking(this.el as HTMLElement, { eventType: 'close' });
    }
  }
  private async expandHandler() {
    this.expanded = !this.expanded;
    await this._expand(this.expanded);
  }
  private handleBackdropClick = (event: MouseEvent) => {
    if (event.target !== event.currentTarget) {
      return;
    }
    asObject(this.closeable)?.backdrop !== false && this.closeHandler('backdropClick');
  };
  private clearAnimations() {
    this.activeAnimations.forEach((animation) => {
      try {
        animation.cancel();
      } catch {
        // ignore
      }
    });
    this.activeAnimations = [];
  }

  private setDrawerTransform(transform: string) {
    if (this.drawerTransform !== transform) {
      this.drawerTransform = transform;
    }
    if (this.drawerRef) {
      this.drawerRef.style.transform = transform;
    }
  }

  private setBackdropOpacity(opacity: string) {
    if (this.backdropOpacity !== opacity) {
      this.backdropOpacity = opacity;
    }
    if (this.backdropRef) {
      this.backdropRef.style.opacity = opacity;
    }
  }

  private syncVisibility(val: boolean) {
    this.animationTargetOpen = undefined;
    if (this.innerVisible !== val) {
      this.innerVisible = val;
    }

    this.setDrawerTransform(`translateX(${val ? '0' : this.translateXOffset})`);
    this.setBackdropOpacity(val ? '1' : '0');
  }

  private finalizeVisibility(val: boolean) {
    this.animationTargetOpen = undefined;

    if (!val) {
      this.innerVisible = false;
    }

    this.setDrawerTransform(`translateX(${val ? '0' : this.translateXOffset})`);
    this.setBackdropOpacity(val ? '1' : '0');
  }

  private visibleByAnime(val: boolean): Promise<boolean> {
    const duration = this.size === 'lg' ? 400 : 350;
    const token = ++this.transitionToken;
    const { translateXOffset } = this;

    this.clearAnimations();
    this.animationTargetOpen = val;

    if (val) {
      this.innerVisible = true;
    }

    this.setDrawerTransform(`translateX(${val ? translateXOffset : '0'})`);
    this.setBackdropOpacity(val ? '0' : '1');

    const animations = [
      this.drawerRef?.animate?.(
        [
          { transform: `translateX(${val ? translateXOffset : '0'})` },
          { transform: `translateX(${val ? '0' : translateXOffset})` },
        ],
        {
          duration,
          easing: val ? 'cubic-bezier(0.4, 0, 0.2, 1)' : 'cubic-bezier(0.32, 0, 0.67, 0)',
          fill: 'forwards',
        },
      ),
      this.backdropRef?.animate?.([{ opacity: val ? '0' : '1' }, { opacity: val ? '1' : '0' }], {
        duration: 200,
        easing: 'cubic-bezier(0.4, 0, 0.2, 1)',
        fill: 'forwards',
      }),
    ].filter(Boolean) as Animation[];

    this.activeAnimations = animations;

    if (animations.length === 0) {
      if (token !== this.transitionToken) {
        return Promise.resolve(false);
      }
      this.activeAnimations = [];
      this.finalizeVisibility(val);
      return Promise.resolve(true);
    }

    return Promise.all(
      animations.map(
        (animation) =>
          new Promise<void>((resolve) => {
            let settled = false;
            const settle = () => {
              if (settled) {
                return;
              }
              settled = true;
              resolve();
            };

            animation.onfinish = settle;
            animation.oncancel = settle;

            if (animation.finished && typeof animation.finished.then === 'function') {
              animation.finished.then(settle).catch(settle);
            }
          }),
      ),
    ).then(() => {
      if (token !== this.transitionToken || this.animationTargetOpen !== val) {
        return false;
      }
      this.activeAnimations = [];
      this.finalizeVisibility(val);
      return true;
    });
  }

  componentWillLoad() {
    this.innerVisible = Boolean(this.mergedOpen);
    this.animationTargetOpen = this.innerVisible ? true : undefined;
    this.drawerTransform = `translateX(${this.innerVisible ? '0' : this.translateXOffset})`;
    this.backdropOpacity = this.innerVisible ? '1' : '0';
  }

  componentDidLoad() {
    this.clearAnimations();
    this.syncVisibility(Boolean(this.mergedOpen));
    this.didLoad = true;
    if (!this.bodyResizeObserver) {
      this.bodyResizeObserver = new ResizeObserver((entries) => {
        entries.forEach((entry) => {
          this._bodyScrollable = entry.target.scrollHeight > entry.target.clientHeight;
        });
      });
      if (this.bodyRef) {
        this.bodyResizeObserver.observe(this.bodyRef);
      }
    }
  }

  disconnectedCallback() {
    if (this.tooltipTimeout) {
      clearTimeout(this.tooltipTimeout);
      this.tooltipTimeout = undefined;
    }

    if (this.bodyResizeObserver) {
      this.bodyResizeObserver.disconnect();
      this.bodyResizeObserver = undefined;
    }

    this.clearAnimations();
  }

  get styles(): CSSProperties {
    return {
      width: formatCSSLength(this.width),
      height: `calc(100vh - ${formatCSSLength(this.topOffset)})`,
      top: formatCSSLength(this.topOffset),
    };
  }

  private renderDrawerSide() {
    const closeButton = asObject(this.closeable)?.icon !== false && (
      <ks-icon-button
        class={`${prefix}__close`}
        variant="secondary"
        loading={this.cancelLoading}
        onClick={() => this.closeHandler('closeIconClick')}
        data-testid="ks-drawer-index-d44ASF"
      >
        <KsIconClose />
      </ks-icon-button>
    );

    const expandButton = (
      <ks-tooltip
        placement="top-start"
        inverse
        open={this.expandTooltipOpen}
        content={this.expandTooltipOpen ? (this.expanded ? 'Collapse' : 'Expand') : ''}
        delay={expandTooltipDelay}
      >
        <ks-icon-button
          class={`${prefix}__expand`}
          variant="text"
          onClick={this.expandHandler.bind(this)}
          onPointerDown={() => this.setTooltipFor(false, 300)}
          onPointerEnter={() => this.setTooltipFor(true, 70)}
          onPointerLeave={() => this.setTooltipFor(false, 70)}
          data-testid="ks-drawer-index-6wwsQv"
        >
          {this.expanded ? <KsIconFold /> : <KsIconUnfold />}
        </ks-icon-button>
      </ks-tooltip>
    );

    if (!this.hasSideNav) {
      return closeButton;
    }

    return (
      <div class={`${prefix}__side-nav`}>
        <div class={`${prefix}__side-nav-top`}>
          {closeButton}
          <slot name="sideNav"></slot>
        </div>
        {this.expandable && expandButton}
      </div>
    );
  }

  render() {
    const classes = `${prefix} ${prefix}--${this.size} ${prefix}--${this.innerPlacement} ${this.expanded ? `${prefix}--expanded` : ''}`;
    const zIndexOverride =
      this.zIndex === undefined || this.zIndex === null || !Number.isFinite(Number(this.zIndex))
        ? undefined
        : Number(this.zIndex);

    return (
      <Host class="KsDrawer">
        <ks-overlay
          mode={this.backdrop ? 'modal' : 'modeless'}
          open={this.innerVisible}
          captureEscape
          closeByEscape={asObject(this.closeable)?.keyboard !== false}
          onKsRequestClose={() => this.closeHandler('keyboard')}
          data-testid="ks-drawer-index-aGYroL"
          deprecatedDisableTopLayer={typeof zIndexOverride === 'number'}
          zIndex={zIndexOverride}
        >
          <div
            class={{ [`${prefix}__underlay`]: true, [`${prefix}__underlay--visible`]: this.innerVisible }}
            style={{
              top: formatCSSLength(this.topOffset),
              width: this.backdrop ? '' : 'fit-content',
            }}
          >
            {this.backdrop && (
              <div
                ref={(el) => (this.backdropRef = el)}
                part="backdrop"
                class={{ [`${prefix}__backdrop`]: true, [`${prefix}__backdrop--open`]: this.innerVisible }}
                style={{
                  top: formatCSSLength(this.topOffset),
                  opacity: this.backdropOpacity,
                }}
                onClick={this.handleBackdropClick}
                data-testid="ks-drawer-index-nidsTB"
              />
            )}

            <div
              ref={(el) => (this.drawerRef = el)}
              class={classes}
              part="base"
              style={{ ...this.styles, transform: this.drawerTransform }}
            >
              <div class={`${prefix}__wrapper`} style={{ paddingBottom: this.footerSlots ? undefined : '0' }}>
                <div class={{ [`${prefix}__side`]: true, [`${prefix}__side--absolute`]: !this.hasSideNav }} part="side">
                  {this.renderDrawerSide()}
                </div>

                <div class={`${prefix}__panel`}>
                  {(this.title || this.headerSlots) && (
                    <slot name="header">
                      <div
                        class={{ [`${prefix}__header`]: true, [`${prefix}__header--dividered`]: this._showDivider }}
                        part="header"
                      >
                        {this.title}
                      </div>
                    </slot>
                  )}

                  <slot name="body">
                    <div
                      class={`${prefix}__body`}
                      part="body"
                      ref={(el) => {
                        this.bodyRef = el;
                        if (el && this.bodyResizeObserver) {
                          this.bodyResizeObserver.observe(el);
                        }
                      }}
                    >
                      <slot></slot>
                    </div>
                  </slot>

                  {this.footerSlots && (
                    <div
                      class={{ [`${prefix}__footer`]: true, [`${prefix}__footer--dividered`]: this._showDivider }}
                      part="footer"
                    >
                      <slot name="footer"></slot>
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        </ks-overlay>
      </Host>
    );
  }
}
